from preview import *
def first(t): return f'<div class="first"><p class="h">먼저 알아둘 것</p><p>{t}</p></div>'
def card(h,body,small=''): return f'<section class="card"><h2 class="q">{h}'+(f' <small>{small}</small>' if small else '')+f'</h2>{body}</section>'
def table(title,rows): return card(title,'<div class="rows">'+''.join(f'<div><b>{a}</b>{b}</div>' for a,b in rows)+'</div>')
def warn(items): return '<div class="warn"><p class="h">실전 팁 · 주의할 점</p><ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul></div>'
def faq(qs,src): return '<section class="card faq"><h2 class="q">자주 묻는 질문</h2>'+''.join(f'<details><summary>{q}</summary><div class="a">{a}</div></details>' for q,a in qs)+f'<p class="src">근거 자료: {src}</p></section>'
def intro(t): return f'<p class="intro">{t}</p>'
